private int nrRendor = 1;
System.Data.DataTable dt;

private void Rap_Format_Printimi_Magazina_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	/*
	ruajme datasetin si nje kopje te vecante, dhe jo si nje reference
	pastrojme datasetin origjinal dhe shtojme 3 rreshta bosh qe detail band te printohet 3 here
	*/
	dt = ((System.Data.DataSet)(this.DataSource)).Tables[0].Copy();
	((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Clear();
      ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();
      ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();
      ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();
	double totaliVlefta = 0;

	for (int i = 0; i < dt.Rows.Count;i++)
	{
		if(dt.Rows[i]["VLEFTA"] != DBNull.Value && dt.Rows[i]["VLEFTA"] != "")
			totaliVlefta += Convert.ToDouble(dt.Rows[i]["VLEFTA"]);
		else 
			totaliVlefta = 0;
	}
	if (dt.Rows.Count > 0)
      	setData(dt.Rows[0], totaliVlefta );
}

private void setData(System.Data.DataRow row,double totali)
{
	xrTableCell21.Text = String.Format("{0:N2}",row["PERSHKRIMKONFIGAMBJENTE"]);
	xrTableCell17.Text = String.Format("{0:N2}",row["NRDOK"]);
	xrTableCell18.Text = String.Format("{0:dd/MM/yyyy}",Convert.ToDateTime(row["DTDOK"]));	
	xrTableCell11.Text = String.Format("{0:N2}",totali);
}

private void xrTable1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) 
{
	shtoRreshtatNeTabele(xrTable1);
}

private void shtoRreshtatNeTabele(XRTable xrTable2)
{
	int i = 0;
	if(dt.Rows.Count > 0)
	{
		for (int j = xrTable2.Rows.Count - 1; j >= 1; j--)
                {
                    xrTable2.Rows.RemoveAt(j);
                }

		Font arial = new Font("Times New Roman", 9.75F, FontStyle.Regular);
            PaddingInfo padding = new PaddingInfo(0, 0, 0, 0);
            BorderSide borders = ((BorderSide)(((BorderSide.Left | BorderSide.Top) | BorderSide.Bottom)));

		foreach (System.Data.DataRow row in dt.Rows)
                {
                    XRTableRow newRow = new XRTableRow();
                    newRow.HeightF = 20f;
				//kodiMag
                   XRTableCell kodi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(85.29f, "" , row["KODI"].ToString(), arial, Color.Black, Color.Transparent, TextAlignment.MiddleLeft, BorderSide.Left, padding);
                   newRow.Cells.Add(kodi);
				//nrRend
                    XRTableCell nrRend = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(42.71f, "" , (nrRendor++).ToString(), arial, Color.White, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    newRow.Cells.Add(nrRend);
				//kodArtikulli
                    XRTableCell kodArtikulli = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(89.58f, "" , row["KODARTIKULLI"].ToString(), arial, Color.White, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                   newRow.Cells.Add(kodArtikulli);
                    	//pershkrimArtikulli
			  XRTableCell pershkrimArtikulli = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(227.08f, "" , row["PERSHKRIMARTIKULLI"].ToString(), arial, Color.White, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                  newRow.Cells.Add(pershkrimArtikulli);
				//kodNjesia
			 XRTableCell kodNjesia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(57.29f, "" , row["KODNJESIA"].ToString(), arial, Color.White, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                   newRow.Cells.Add(kodNjesia);
				//sasia
			XRTableCell sasia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(67.71f, "" , row["SASIA"].ToString(), arial, Color.White, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
                  newRow.Cells.Add(sasia);
				//cmimi
			 XRTableCell cmimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(78.12f, "" , String.Format("{0:N2}",row["CMIMI"]), arial, Color.White, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
                    newRow.Cells.Add(cmimi);
				//vlefta
			 XRTableCell vlefta = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(79.21f, "" , String.Format("{0:N2}",row["VLEFTA"]), arial, Color.Black, Color.Transparent, TextAlignment.MiddleRight,BorderSide.Right, padding);
                    newRow.Cells.Add(vlefta);

                    xrTable2.Rows.Insert((i + 1), newRow);
                i++;
               }
	nrRendor = 1;

	}
}
